Triangulation3 delaunayTriangulation3D(const std::vector<Point3d>& points) {
    Triangulation3 result;

    for (const Point3d& p : points) {
        result.triangulation.insert(CGAL::Point_3<Triangulation3::K>(p.x(), p.y(), p.z()));
    }

    return result;
}

